
import { useContext } from "react";
import AllComponent from "../Component/AllComponent";
import { apiValue } from "../Data/AllData";
import { CartProvider, useCart } from "react-use-cart";

function Product() {
  const { addItem } = useCart();
  const data = useContext(apiValue);

  return (
    <div className="property py-5" style={{ minHeight: "120vh",marginTop:"150px" }}>
      <div className="container">
        {/* صف المنتجات */}
        <div className="row g-4 m">
          {data.map((item) => (
            <div key={item.id} className="col-md-4 col-sm-6">
              <div
                className="rounded position-relative border border-secondary h-100"
                style={{
                  transition: "0.3s",
                  overflow: "hidden",
                  boxShadow: "0 2px 6px rgba(0,0,0,0.1)",
                }}
              >
                <div className="fruite-img">
                  <img
                    src={item.images[0]}
                    className="img-fluid w-100 rounded-top"
                    alt={item.title}
                    style={{ height: "250px", objectFit: "cover" }}
                  />
                </div>

                <div
                  className="text-white bg-secondary px-3 py-1 rounded position-absolute"
                  style={{ top: 10, left: 10 }}
                >
                  Fruits
                </div>

                <div className="p-3 text-center">
                  <h5>{item.title}</h5>
                  <p className="text-muted mb-1">ID: {item.id}</p>
                  <h6 className="text-success mb-3">${item.price}</h6>

                  <button
                    className="btn btn-dark btn-sm"
                    onClick={() => addItem(item)}
                  >
                    Add To Cart
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

function AllProduct() {
  return (
    <CartProvider>
      <AllComponent />
      <Product />
    </CartProvider>
  );
}

export default AllProduct;




