
import { useCart } from "react-use-cart";
import AllComponent from "../Component/AllComponent";
import Copy from "../Shop/Copy";

import Model from "../Shop/Model";
import Section from "../Shop/Section";
import Single from "../Shop/Single";
import { useContext } from "react";
import { apiValue } from "../Data/AllData";
import { Link } from "react-router";


function Page(){
     const {addItem}=useCart();
    const data=useContext(apiValue);
    return(
        <div>
   <div className="section properties">
    <div className="container">
        <div className="row properties-box">
{ data.map((item)=>{
return(
    <div>  
<div className="col-md-4 col-lg-4 col-xl-4">
            <div className="row g-4 justify-content-center">
           
                <div className="rounded position-relative fruite-item">
                    
                  <div className="fruite-img">
                    <img  src={item.images[0]}
                      className="img-fluid w-100 rounded-top"
                      alt=""/>
                  </div>
                  <div
                    className="text-white bg-secondary px-3 py-1 rounded position-absolute"
                    style={{ top: 10, left: 10 }}
                  >
                    Fruits
                  </div>
                  <div className="p-4 border border-secondary border-top-0 rounded-bottom">
                    <h4>Grapes</h4>
                    <p>{item.title}</p>
                    <h3> {item.id}</h3>
                    <h3> {item.price}</h3>
                  <div className="main-button">
                    <button className="btn btn-dark" onClick={()=>addItem(item)}> Add To Cart</button>
                  </div>
                    
                  </div>
                </div>
              </div>









          
   
              </div>

    </div>
)
,[]})}
        </div>

    </div>
   </div>
  

        </div>
    )
}

function AllShop(){

    return(
        <div>
 <AllComponent/>
 <Page/>
 <Model/>
<Single/>

<Section/>


<Copy/>
        </div>
    )
}
export default AllShop;