import { CartProvider, useCart } from "react-use-cart";
import AllComponent from "../Component/AllComponent";
import { Link } from "react-router";

function AllCart(){
const {items,updateItemQuantity,removeItem,totalItems,totalUniqueItems,cartTotal,isEmpty}=useCart();
        if(isEmpty){
            return(
                <div>
                  <br></br>
                  <br></br>
                  <br></br>
                  <br></br>
                  <br></br>
                  <br></br>
                  <br></br>
                    <h2 className="text-center"> Your Cart IS Empathy </h2>
              
                 
                </div>
            )
        }

    return(
        <div>
<main className="page">
  <section className="shopping-cart dark">
    <div className="container">
      <div className="block-heading">
        <br></br>
        <br></br>
        <br></br>
        <br></br>
        <br></br>
        <br></br>
        <br></br>
        <br></br>
        <h2>Shopping Cart( { totalUniqueItems})</h2>
    
      </div>
      <div className="content">
        <div className="row">
          <div className="col-md-12 col-lg-8">
            <div className="items">
                {items.map((item)=>{
                    return(
              <div className="product">
                <div className="row">
                  <div className="col-md-3">
                    <img
                      className="img-fluid  h-100 w-100 d-block image"
                      src={item.images[0]}
                    />
                  </div>
                  <div className="col-md-8">
                    <div className="info">
                      <div className="row">
                        <div className="col-md-5 product-name">
                          <div className="product-name">
                            <a href="#">{item.title}</a>
                        
                          </div>
                        </div>
                        <div className="col-md-4 quantity">
                          <label htmlFor="quantity">Quantity:</label>
                       <p>{ item.quantity}</p>
                       <button className="btn btn-warning" onClick={()=>updateItemQuantity(item.id,item.quantity-1)}>-</button>
                       <button  className="btn btn-success mx-3" onClick={()=>updateItemQuantity(item.id,item.quantity+1)}>+</button>
                       <button  className="btn btn-danger" onClick={()=>removeItem(item.id)}>&times;</button>
                        </div>
                        <div className="col-md-3 price">
                          <span> {Math.ceil( item.price*item.quantity)}$</span>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
                      
                    )
                })}
            
            
            </div>
          </div>
          <div className="col-md-12 col-lg-4">
            <div className="summary">
              <h3>Summary</h3>
              <div className="summary-item">
                <span className="text">Subtotal</span>
                <span className="price">${Math.ceil(cartTotal)}</span>
              </div>
              <div className="summary-item">
                <span className="text">Discount</span>
                <span className="price">$0</span>
              </div>
              <div className="summary-item">
                <span className="text">Shipping</span>
                <span className="price">$0</span>
              </div>
              <div className="summary-item">
                <span className="text">Total</span>
                <span className="price">$360</span>
              </div>
              <Link
              to="/check"
                type="button"
                className="btn btn-primary btn-lg btn-block"
              >
                Checkout
              </Link>
            </div>
          </div>
        </div>
      </div>
    </div>
  </section>
</main>

        </div>
    )
}

function  Cart(){

    return(
        <CartProvider>
       <AllComponent/>
        <AllCart/>
        </CartProvider>
    )
}
export default Cart;